class ModuleDepFinder(ast.NodeVisitor):

    def __init__(self, module_fqn, is_package=False, *args, **kwargs):
        """
        Walk the ast tree for the python module.
        :arg module_fqn: The fully qualified name to reach this module in dotted notation.
            example: ansible.module_utils.basic

        Save submodule[.submoduleN][.identifier] into self.submodules
        when they are from ansible.module_utils or ansible_collections packages

        self.submodules will end up with tuples like:
          - ('ansible', 'module_utils', 'basic',)
          - ('ansible', 'module_utils', 'urls', 'fetch_url')
          - ('ansible', 'module_utils', 'database', 'postgres')
          - ('ansible', 'module_utils', 'database', 'postgres', 'quote')
          - ('ansible', 'module_utils', 'database', 'postgres', 'quote')
          - ('ansible_collections', 'my_ns', 'my_col', 'plugins', 'module_utils', 'foo')

        It's up to calling code to determine whether the final element of the
        tuple are module names or something else (function, class, or variable names)
        .. seealso:: :python3:class:`ast.NodeVisitor`
        """
        super(ModuleDepFinder, self).__init__(*args, **kwargs)
        self.submodules = set()
        self.ambiguous = set()
        self.module_fqn = module_fqn
        self.is_package = is_package

        self._visit_map = {
            Import: self.visit_Import,
            ImportFrom: self.visit_ImportFrom,
        }

    def generic_visit(self, node):
        """Overridden ``generic_visit`` that makes some assumptions about our
        use case, and improves performance by calling visitors directly instead
        of calling ``visit`` to offload calling visitors.
        """
        visit_map = self._visit_map
        generic_visit = self.generic_visit
        for field, value in ast.iter_fields(node):
            if isinstance(value, list):
                for item in value:
                    if isinstance(item, (Import, ImportFrom)):
                        visit_map[item.__class__](item)
                    elif isinstance(item, AST):
                        generic_visit(item)

    visit = generic_visit

    def visit_Import(self, node):
        """
        Handle import ansible.module_utils.MODLIB[.MODLIBn] [as asname]

        We save these as interesting submodules when the imported library is in ansible.module_utils
        or ansible.collections
        """
        for alias in node.names:
            if (alias.name == 'ansible.module_utils' or alias.name.startswith('ansible.module_utils.') or
                    alias.name.startswith('ansible_collections.') and
                    (alias.name.endswith('.plugins.module_utils') or '.plugins.module_utils.' in alias.name)):
                py_mod = tuple(alias.name.split('.'))
                self.submodules.add(py_mod)
        self.generic_visit(node)

    def visit_ImportFrom(self, node):
        """
        Handle from ansible.module_utils.MODLIB import [.MODLIBn] [as asname]

        Also has to handle relative imports

        We save these as interesting submodules when the imported library is in ansible.module_utils
        or ansible.collections
        """

        # FIXME: These should all get skipped:
        # from ansible.executor import module_common
        # from ...executor import module_common
        # from ... import executor (Currently it gives a non-helpful error)
        if node.level > 0:
            if self.module_fqn:
                parts = tuple(self.module_fqn.split('.'))
                # A package initializer lives inside its package. Treat the
                # implicit __init__ module as the final component when
                # calculating how many levels a relative import climbs.
                if self.is_package and parts[-1] != '__init__':
                    parts += ('__init__',)
                if node.module:
                    # relative import: from .module import x
                    node_module = '.'.join(parts[:-node.level] + (node.module,))
                else:
                    # relative import: from . import x
                    node_module = '.'.join(parts[:-node.level])
            else:
                # fall back to an absolute import
                node_module = node.module
        else:
            # absolute import: from module import x
            node_module = node.module

        # Specialcase: six is a special case because of its
        # import logic
        py_mod = None
        if node.names[0].name == '_six':
            self.submodules.add(('_six',))
        elif node_module and node_module.startswith('ansible.module_utils'):
            # from ansible.module_utils.MODULE1[.MODULEn] import IDENTIFIER [as asname]
            # from ansible.module_utils.MODULE1[.MODULEn] import MODULEn+1 [as asname]
            # from ansible.module_utils.MODULE1[.MODULEn] import MODULEn+1 [,IDENTIFIER] [as asname]
            # from ansible.module_utils import MODULE1 [,MODULEn] [as asname]
            py_mod = tuple(node_module.split('.'))

        elif node_module and node_module.startswith('ansible_collections.'):
            if node_module.endswith('plugins.module_utils') or '.plugins.module_utils.' in node_module:
                # from ansible_collections.ns.coll.plugins.module_utils import MODULE [as aname] [,MODULE2] [as aname]
                # from ansible_collections.ns.coll.plugins.module_utils.MODULE import IDENTIFIER [as aname]
                # FIXME: Unhandled cornercase (needs to be ignored):
                # from ansible_collections.ns.coll.plugins.[!module_utils].[FOO].plugins.module_utils import IDENTIFIER
                py_mod = tuple(node_module.split('.'))
            else:
                # Not from module_utils so ignore.  for instance:
                # from ansible_collections.ns.coll.plugins.lookup import IDENTIFIER
                pass

        if py_mod:
            for alias in node.names:
                imported = py_mod + (alias.name,)
            else:
                interpreter_out = facts_from_task_vars[discovered_interpreter_config]
    else:
        # a config def does not exist for this interpreter type; consult vars for a possible direct override
        interpreter_config = u'ansible_%s_interpreter' % interpreter_name

        if interpreter_config not in task_vars:
            return None, interpreter

        interpreter_out = templar.template(task_vars[interpreter_config].strip())

    shebang = u'#!' + interpreter_out

    if args:
        shebang = shebang + u' ' + u' '.join(args)

    return shebang, interpreter_out


class ModuleInfo:
    def __init__(self, name, paths):
        self.py_src = False
        self.pkg_dir = False
        path = None

        if imp is None:
            # don't pretend this is a top-level module, prefix the rest of the namespace
            self._info = info = importlib.machinery.PathFinder.find_spec('ansible.module_utils.' + name, paths)
            if info is not None:
                if info.origin is None and info.submodule_search_locations:
                    # A directory without __init__.py is still a package in
                    # the module payload, which requires an init file.
                    self.py_src = True
                    self.pkg_dir = True
                    path = os.path.join(info.submodule_search_locations[0], '__init__.py')
                elif info.origin is not None:
                    self.py_src = os.path.splitext(info.origin)[1] in importlib.machinery.SOURCE_SUFFIXES
                    self.pkg_dir = info.origin.endswith('/__init__.py')
                    path = info.origin
                else:
                    raise ImportError("No module named '%s'" % name)
            else:
                raise ImportError("No module named '%s'" % name)
        else:
            self._info = info = imp.find_module(name, paths)
            self.py_src = info[2][2] == imp.PY_SOURCE
            self.pkg_dir = info[2][2] == imp.PKG_DIRECTORY
            if self.pkg_dir:
                path = os.path.join(info[1], '__init__.py')
            else:
                path = info[1]

        self.path = path

    def get_source(self):
        if self.pkg_dir and not os.path.isfile(self.path):
            return b''
        if imp and self.py_src:
            try:
                return self._info[0].read()
            finally:
                self._info[0].close()
        return _slurp(self.path)

    def __repr__(self):
        return 'ModuleInfo: py_src=%s, pkg_dir=%s, path=%s' % (self.py_src, self.pkg_dir, self.path)


class ModuleUtilLocatorBase:
    """Resolve one import without executing module_utils code on the controller."""

    root_length = 0
    redirect_first = False

    def __init__(self, fq_name_parts, is_ambiguous=False, child_is_redirected=False):
        self.fq_name_parts = tuple(fq_name_parts)
        self.is_ambiguous = is_ambiguous
        self.child_is_redirected = child_is_redirected
        self.found = False
        self.redirected = False
        self.is_package = False
        self.name_parts = self.fq_name_parts
        self.source = None
        self.source_path = None
        self.redirect_target = None
        self.output_path = None
        self._candidate_names = [self.fq_name_parts]
        if is_ambiguous and len(self.fq_name_parts) > self.root_length + 1:
            self._candidate_names.append(self.fq_name_parts[:-1])

        for candidate in self._candidate_names:
            if self._resolve(candidate):
                break

    def candidate_names_joined(self):
        return ['.'.join(parts) for parts in self._candidate_names]

    @staticmethod
    def _expand_redirect(target):
        if target.startswith('ansible_collections.') or target.startswith('ansible.module_utils.'):
            return tuple(target.split('.'))
        parts = tuple(target.split('.'))
        if len(parts) < 3:
            raise AnsibleError('Invalid module_utils redirect target %s' % target)
        if parts[:2] == ('ansible', 'builtin'):
            return ('ansible', 'module_utils') + parts[2:]
        return ('ansible_collections',) + parts[:2] + ('plugins', 'module_utils') + parts[2:]

    def _routing(self, parts):
        return None

    def _local(self, parts):
        return None

    def _redirect_entry(self, parts):
        entry = self._routing(parts)
        if entry:
            return entry, ()
        # A redirected package also redirects imports below it. Its shim
        # aliases the real package, preserving the latter's __path__.
        for length in range(len(parts) - 1, self.root_length, -1):
            if not self.redirect_first and self._local(parts[:length]) is not None:
                # A local legacy package overrides routing for its children.
                break
            entry = self._routing(parts[:length])
            if entry and entry.get('redirect'):
                return entry, parts[length:]
        return None, ()

    def _use_redirect(self, parts):
        entry, suffix = self._redirect_entry(parts)
        if not entry:
            return False
        collection = self.collection_name
        tombstone = entry.get('tombstone') or {}
        if tombstone:
            message = display.get_deprecation_message(
                tombstone.get('warning_text') or '%s has been removed' % '.'.join(parts),
                version=tombstone.get('removal_version'), date=tombstone.get('removal_date'),
                removed=True, collection_name=collection)
            raise AnsibleError(message)
        if not entry.get('redirect'):
            return False
        target = self._expand_redirect(entry['redirect']) + suffix
        if suffix and self.is_ambiguous and parts == self.fq_name_parts:
            # In "from redirected_package import name", name may be an
            # attribute of the package rather than a child module.
            if target[:2] == ('ansible', 'module_utils'):
                probe = LegacyModuleUtilLocator(target, mu_paths=getattr(self, 'mu_paths', None))
            else:
                probe = CollectionModuleUtilLocator(target)
            if not probe.found:
                return False
        deprecation = entry.get('deprecation') or {}
        if deprecation:
            display.deprecated(deprecation.get('warning_text') or '%s has been deprecated' % '.'.join(parts),
                               version=deprecation.get('removal_version'), date=deprecation.get('removal_date'),
                               collection_name=collection)
        self.found = True
        self.redirected = True
        self.name_parts = parts
        self.redirect_target = target
        self.source = ("from importlib import import_module as _import_module\n"
                       "import sys as _sys\n"
                       "_sys.modules[__name__] = _import_module(%r)\n" % '.'.join(target)).encode('utf-8')
        self.source_path = 'redirect to ' + '.'.join(target)
        # The shim can be imported as a module even when the target is a
        # package: sys.modules then contains that package and its __path__.
        self.is_package = False
        self.output_path = '/'.join(parts) + '.py'
        return True

    def _resolve(self, parts):
        if self.redirect_first and self._use_redirect(parts):
            return True
        local = self._local(parts)
        if local is not None:
            self.found = True
            self.name_parts = parts
            self.source, self.source_path, self.is_package = local
            self.output_path = '/'.join(parts) + ('/__init__.py' if self.is_package else '.py')
            return True
        if not self.redirect_first and self._use_redirect(parts):
            return True
        return False


class LegacyModuleUtilLocator(ModuleUtilLocatorBase):
    root_length = 2
    collection_name = 'ansible.builtin'

    def __init__(self, fq_name_parts, is_ambiguous=False, mu_paths=None, child_is_redirected=False):
        self.mu_paths = mu_paths if mu_paths is not None else [
            p for p in module_utils_loader._get_paths(subdirs=False) if os.path.isdir(p)] + [_MODULE_UTILS_PATH]
        super(LegacyModuleUtilLocator, self).__init__(fq_name_parts, is_ambiguous, child_is_redirected)

    def _routing(self, parts):
        if len(parts) <= self.root_length:
            return None
        metadata = _get_collection_metadata('ansible.builtin')
        entry = metadata.get('plugin_routing', {}).get('module_utils', {}).get('.'.join(parts[2:]))
        return entry or metadata.get('import_redirection', {}).get('.'.join(parts))

    def _local(self, parts):
        if len(parts) <= self.root_length:
            return b'', '/'.join(parts) + '/__init__.py', True
        if parts[:3] == ('ansible', 'module_utils', 'six'):
            parts = parts[:3]
        relative = parts[2:]
        paths = [os.path.join(p, *relative[:-1]) for p in self.mu_paths]
        try:
            info = ModuleInfo(relative[-1], paths)
        except ImportError:
            return None
        if not info.pkg_dir and not info.py_src:
            raise AnsibleError('Could not find python source for imported module support code %s' % '.'.join(parts))
        # The wrapper always needs basic.py; retain its module shape even if
        # a loader or test double reports it as a package.
        return info.get_source(), info.path, bool(info.pkg_dir and relative != ('basic',))

    def _resolve(self, parts):
        if parts[:3] == ('ansible', 'module_utils', 'six'):
            parts = parts[:3]
        elif parts[:3] == ('ansible', 'module_utils', '_six'):
            parts = ('ansible', 'module_utils', 'six')
        return super(LegacyModuleUtilLocator, self)._resolve(parts)


class CollectionModuleUtilLocator(ModuleUtilLocatorBase):
    root_length = 5
    redirect_first = True

    @property
    def collection_name(self):
        return '.'.join(self.fq_name_parts[1:3])

    def _collection(self):
        try:
            metadata = _get_collection_metadata(self.collection_name)
            package = import_module('ansible_collections.' + self.collection_name)
        except (ImportError, ValueError) as e:
            raise AnsibleError('unable to locate collection %s: %s' % (self.collection_name, to_native(e)))
        return metadata, package

    def _routing(self, parts):
        if len(parts) <= self.root_length:
            return None
        metadata, unused = self._collection()
        return metadata.get('plugin_routing', {}).get('module_utils', {}).get('.'.join(parts[5:]))

    def _local(self, parts):
        if len(parts) < self.root_length:
            return b'', '/'.join(parts) + '/__init__.py', True
        unused, package = self._collection()
        if len(parts) == self.root_length:
            return b'', '/'.join(parts) + '/__init__.py', True
        for collection_path in getattr(package, '__path__', ()):
            path = os.path.join(collection_path, *parts[3:])
            init_path = os.path.join(path, '__init__.py')
            if os.path.isdir(path):
                return (_slurp(init_path) if os.path.isfile(init_path) else b''), init_path, True
            module_path = path + '.py'
            if os.path.isfile(module_path):
                return _slurp(module_path), module_path, False
        return None


def recursive_finder(name, module_fqn, data, py_module_names, py_module_cache, zf):
    """Add module_utils dependencies to *zf* using a work queue.

    py_module_names tracks files already added to the payload. Dependencies
    found in a file are queued for resolution, so deep import chains do not
    depend on the Python call stack.
    """
    module_utils_paths = [p for p in module_utils_loader._get_paths(subdirs=False) if os.path.isdir(p)]
    module_utils_paths.append(_MODULE_UTILS_PATH)
    pending = deque((('scan', name, module_fqn, data),
                     ('resolve', ('ansible', 'module_utils', 'basic'), False, module_fqn)))
    redirect_targets = {}

    def locator_for(parts, ambiguous=False, child_is_redirected=False):
        if parts == ('_six',):
            parts = ('ansible', 'module_utils', 'six')
        if parts[:2] == ('ansible', 'module_utils'):
            return LegacyModuleUtilLocator(parts, ambiguous, module_utils_paths, child_is_redirected)
        if parts and parts[0] == 'ansible_collections':
            return CollectionModuleUtilLocator(parts, ambiguous, child_is_redirected)
        display.warning('ModuleDepFinder improperly found a non-module_utils import %s' % (parts,))
        return None

    def add_file(locator):
        key = locator.name_parts + (('__init__',) if locator.is_package else ())
        if key in py_module_names:
            return
        if locator.redirected:
            cursor = locator.redirect_target
            while True:
                if cursor == locator.name_parts:
                    raise AnsibleError('Circular module_utils redirect for %s' % '.'.join(cursor))
                if cursor not in redirect_targets:
                    break
                cursor = redirect_targets[cursor]
            redirect_targets[locator.name_parts] = locator.redirect_target
        py_module_names.add(key)
        py_module_cache[key] = (locator.source, locator.source_path)
        if locator.output_path not in zf.namelist():
            zf.writestr(locator.output_path, locator.source)
        display.vvvvv('Using module_utils file %s' % to_text(locator.source_path, errors='surrogate_or_strict'))
        pending.append(('scan', key[-1], '.'.join(key), locator.source))
        if locator.redirected:
            pending.append(('resolve', locator.redirect_target, False, '.'.join(key)))

    def add_parents(parts):
        for length in range(1, len(parts)):
            parent = parts[:length]
            key = parent + ('__init__',)
            if key in py_module_names or parent in py_module_names:
                continue
            locator = locator_for(parent)
            if locator and locator.found:
                add_file(locator)
            else:
                # Collection namespace and plugin directories, as well as
                # namespace packages in module_utils, need an init in the zip.
                path = '/'.join(parent) + '/__init__.py'
                py_module_names.add(key)
                py_module_cache[key] = (b'', path)
                if path not in zf.namelist():
                    zf.writestr(path, b'')
                pending.append(('scan', '__init__', '.'.join(key), b''))

    while pending:
        work = pending.popleft()
        if work[0] == 'scan':
            unused, module_name, source_fqn, source_data = work
            try:
                tree = compile(source_data, '<unknown>', 'exec', ast.PyCF_ONLY_AST)
            except (SyntaxError, IndentationError) as e:
                raise AnsibleError('Unable to import %s due to %s' % (module_name, e.msg))
            finder = ModuleDepFinder(source_fqn, is_package=source_fqn.endswith('.__init__'))
            finder.visit(tree)
            for parts in sorted(finder.submodules):
                pending.append(('resolve', parts, parts in finder.ambiguous, source_fqn))
            py_module_cache.pop(tuple(source_fqn.split('.')), None)
        else:
            unused, parts, ambiguous, source_fqn = work
            locator = locator_for(parts, ambiguous)
            if locator is None:
                continue
            if not locator.found:
                raise AnsibleError('Could not find imported module support code for %s. Looked for (%s)' %
                                   (source_fqn, ', '.join(locator.candidate_names_joined())))
            add_parents(locator.name_parts)
            add_file(locator)

def _is_binary(b_module_data):
    textchars = bytearray(set([7, 8, 9, 10, 12, 13, 27]) | set(range(0x20, 0x100)) - set([0x7f]))
    start = b_module_data[:1024]
    return bool(start.translate(None, textchars))


def _get_ansible_module_fqn(module_path):
    """
    Get the fully qualified name for an ansible module based on its pathname

    remote_module_fqn is the fully qualified name.  Like ansible.modules.system.ping
    Or ansible_collections.Namespace.Collection_name.plugins.modules.ping
    .. warning:: This function is for ansible modules only.  It won't work for other things
        (non-module plugins, etc)
    """
    remote_module_fqn = None

    # Is this a core module?
    match = CORE_LIBRARY_PATH_RE.search(module_path)
    if not match:
        # Is this a module in a collection?
        match = COLLECTION_PATH_RE.search(module_path)

    # We can tell the FQN for core modules and collection modules
    if match:
        path = match.group('path')
        if '.' in path:
            # FQNs must be valid as python identifiers.  This sanity check has failed.
            # we could check other things as well
            raise ValueError('Module name (or path) was not a valid python identifier')

        remote_module_fqn = '.'.join(path.split('/'))
    else:
        # Currently we do not handle modules in roles so we can end up here for that reason
        raise ValueError("Unable to determine module's fully qualified name")

    return remote_module_fqn


def _add_module_to_zip(zf, remote_module_fqn, b_module_data):
    """Add a module from ansible or from an ansible collection into the module zip"""
    module_path_parts = remote_module_fqn.split('.')

    # Write the module
    module_path = '/'.join(module_path_parts) + '.py'
    zf.writestr(module_path, b_module_data)

    # Write the __init__.py's necessary to get there
    if module_path_parts[0] == 'ansible':
        # The ansible namespace is setup as part of the module_utils setup...
        start = 2
        existing_paths = frozenset()
    else:
        # ... but ansible_collections and other toplevels are not
        start = 1
        existing_paths = frozenset(zf.namelist())

    for idx in range(start, len(module_path_parts)):
        package_path = '/'.join(module_path_parts[:idx]) + '/__init__.py'
        # If a collections module uses module_utils from a collection then most packages will have already been added by recursive_finder.
        if package_path in existing_paths:
            continue
        # Note: We don't want to include more than one ansible module in a payload at this time
        # so no need to fill the __init__.py with namespace code
        zf.writestr(package_path, b'')
